        const down = match ? Number(match[2].replace(',', '.')) : null;
        const amount = match ? total - down : parseFloat(input);
        const invalidDown = 'Ошибка: первоначальный взнос должен быть больше 0 и меньше общей суммы.';
        if (isNaN(amount) || amount <= 0) return { message: match ? invalidDown : 'Ошибка: введите корректную сумму.', title: '🧮 Калькулятор', query: true };
        if (match && (!Number.isFinite(total) || !Number.isFinite(down) || down <= 0 || down >= total)) return { message: invalidDown, title: '🧮 Калькулятор', query: true };
