        const colors = kind === 'error'
            ? ['#fee2e2', '#991b1b', '#fecaca']
            : kind === 'ok' ? ['#dcfce7', '#166534', '#86efac'] : ['#eff6ff', '#1d4ed8', '#bfdbfe'];
        toast.style.background = colors[0];
        toast.style.color = colors[1];
        toast.style.border = `1px solid ${colors[2]}`;
